 if f.endswith('factor_ensemble.json'):continue
 d=json.load(open(f)); m=d.get('validation',{}).get('metrics',{}); s=d.get('benchmark_admission',{}).get('selected_metrics',{})
 if d.get('validation',{}).get('status')=='EFFECTIVE':
  def x(k): return m.get(k) if m.get(k) is not None else s.get(k)
  print(os.path.basename(f), 'IC',x('ic'),'ICIR',x('icir'),'q',s.get('quality'),'turn',m.get('turnover'))
PY

